  ('11111111-1111-4111-8111-111111111113', 'wedding-invitations', 'Wedding Invitations', 'Elegant digital invitations with event details and a simple RSVP.', '/api/template-art/wedding-invitations', false, 130, true),
  ('11111111-1111-4111-8111-111111111114', 'quote-cards', 'Quote Cards', 'Share meaningful words, encouragement, and little reminders as beautiful cards.', '/api/template-art/quote-cards', false, 140, true),
  ('11111111-1111-4111-8111-111111111115', 'baby-showers', 'Baby Showers', 'Warm invitations to celebrate a new arrival with the people you love.', '/api/template-art/baby-showers', false, 150, true)
