  ('22222222-2222-4222-8222-222222222249', 'quote-kindness', 'A Note to Keep', 'A thoughtful quote card for encouragement, gratitude, or a brighter day.', '11111111-1111-4111-8111-111111111114', 'custom', '/api/template-art/quote-kindness', '/api/template-art/quote-kindness', false, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"A thought to carry with you","message":"The smallest moments often become our favorite memories.","theme":{"background":"#F7F0E8","accent":"#84625C","secondary":"#EADFD5","text":"#332B2B"},"animation":{"type":"fade","intensity":"low"},"music":{"enabled":false,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#F7F0E8","accent":"#84625C","secondary":"#EADFD5","text":"#332B2B"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"fade","intensity":"low"}'::jsonb, true, 205),
  ('22222222-2222-4222-8222-222222222250', 'baby-shower-welcome', 'A Little One Is on the Way', 'A joyful baby shower invitation with event details and an RSVP.', '11111111-1111-4111-8111-111111111115', 'custom', '/api/template-art/baby-shower-welcome', '/api/template-art/baby-shower-welcome', false, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"A little one is on the way","message":"Join us for a joyful gathering as we celebrate a new arrival.","date":{"date":"","time":"","venue":"","address":""},"questions":[{"id":"shower-rsvp","question":"Can we save you a seat?","options":["Yes, I will be there","I cannot make it"]}],"theme":{"background":"#F5F1EA","accent":"#718B78","secondary":"#DFE9DE","text":"#2E352F"},"animation":{"type":"fade","intensity":"low"},"music":{"enabled":false,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#F5F1EA","accent":"#718B78","secondary":"#DFE9DE","text":"#2E352F"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"fade","intensity":"low"}'::jsonb, true, 210)
